**Gaps:**
- `generateTaskId`: no test for prefix-per-type, alphabet constraint, ID length, or uniqueness
- `createTaskStateBase`: no test for optional `toolUseId`, `status` default, `outputOffset` default
- `isTerminalTaskStatus`: `'pending'` and `'running'` not explicitly tested as `false`

```ts
// tests/Task.test.ts
import { describe, it, expect } from 'bun:test'
import {
  isTerminalTaskStatus,
  generateTaskId,
  createTaskStateBase,
  type TaskType,
} from '../src/Task.js'

describe('isTerminalTaskStatus', () => {
  it('returns true for completed', () => expect(isTerminalTaskStatus('completed')).toBe(true))
  it('returns true for failed',    () => expect(isTerminalTaskStatus('failed')).toBe(true))
  it('returns true for killed',    () => expect(isTerminalTaskStatus('killed')).toBe(true))
  it('returns false for pending',  () => expect(isTerminalTaskStatus('pending')).toBe(false))
  it('returns false for running',  () => expect(isTerminalTaskStatus('running')).toBe(false))
})

describe('generateTaskId', () => {
  const TYPES: TaskType[] = [
    'local_bash', 'local_agent', 'remote_agent',
    'in_process_teammate', 'local_workflow', 'monitor_mcp', 'dream',
  ]
  const EXPECTED_PREFIXES: Record<TaskType, string> = {
    local_bash: 'b', local_agent: 'a', remote_agent: 'r',
    in_process_teammate: 't', local_workflow: 'w', monitor_mcp: 'm', dream: 'd',
  }

  for (const type of TYPES) {
    it(`prefixes ${type} with '${EXPECTED_PREFIXES[type]}'`, () => {
      expect(generateTaskId(type)).toMatch(new RegExp(`^${EXPECTED_PREFIXES[type]}`))
    })
  }

  it('produces IDs of length 9 (1 prefix + 8 body chars)', () => {
    expect(generateTaskId('local_bash')).toHaveLength(9)
  })

  it('uses only safe alphabet characters', () => {
    const id = generateTaskId('local_agent')
    expect(id).toMatch(/^[0-9a-z]{9}$/)
  })

  it('generates unique IDs across many calls', () => {
    const ids = new Set(Array.from({ length: 1000 }, () => generateTaskId('local_bash')))
    expect(ids.size).toBe(1000)
  })
})

describe('createTaskStateBase', () => {
  it('sets status to pending', () => {
    const s = createTaskStateBase('b12345678', 'local_bash', 'echo hi')
    expect(s.status).toBe('pending')
  })

  it('sets outputOffset to 0 and notified to false', () => {
    const s = createTaskStateBase('b12345678', 'local_bash', 'echo hi')
    expect(s.outputOffset).toBe(0)
    expect(s.notified).toBe(false)
  })

  it('omits toolUseId when not provided', () => {
    const s = createTaskStateBase('b12345678', 'local_bash', 'desc')
    expect(s.toolUseId).toBeUndefined()
  })

  it('includes toolUseId when provided', () => {
    const s = createTaskStateBase('b12345678', 'local_bash', 'desc', 'tool-abc')
    expect(s.toolUseId).toBe('tool-abc')
  })

  it('sets startTime close to Date.now()', () => {
    const before = Date.now()
    const s = createTaskStateBase('b12345678', 'local_bash', 'desc')
    expect(s.startTime).toBeGreaterThanOrEqual(before)
    expect(s.startTime).toBeLessThanOrEqual(Date.now())
  })
})
```

