**Gaps:**
- `redactSecrets`: short values (< 16 chars) — full `[REDACTED]`; long values — partial redact with `...`; multiple secret fields in one string
- `debugTruncate`: newline → `\n`, truncation at 2000, no truncation for short strings
- `extractErrorDetail`: null input, `data.message` priority over `data.error.message`, both absent
- `describeAxiosError`: no `response`, has `response.data.message`, has `response.data.error.message`
- `extractHttpStatus`: non-HTTP error returns `undefined`

```ts
// tests/bridge/debugUtils.test.ts
import { describe, it, expect, mock } from 'bun:test'
import {
  redactSecrets,
  debugTruncate,
  debugBody,
  describeAxiosError,
  extractHttpStatus,
  extractErrorDetail,
} from '../../src/bridge/debugUtils.js'

describe('redactSecrets', () => {
  it('fully redacts short secrets (< 16 chars)', () => {
    const input = '{"token":"abc123"}'
    expect(redactSecrets(input)).toBe('{"token":"[REDACTED]"}')
  })

  it('partially redacts long secrets', () => {
    const input = '{"token":"abcdefghijklmnop1234"}'
    const result = redactSecrets(input)
    expect(result).toContain('abcdefgh')
    expect(result).toContain('...')
    expect(result).not.toContain('abcdefghijklmnop1234')
  })

  it('redacts all listed secret field names', () => {
    const fields = ['session_ingress_token', 'environment_secret', 'access_token', 'secret', 'token']
    for (const field of fields) {
      const longVal = 'a'.repeat(20)
      const result = redactSecrets(`{"${field}":"${longVal}"}`)
      expect(result).not.toContain(longVal)
    }
  })

  it('redacts multiple fields in one string', () => {
    const input = '{"token":"abcdefghijklmnopqr","secret":"stuvwxyz12345678"}'
    const result = redactSecrets(input)
    expect(result).not.toContain('abcdefghijklmnopqr')
    expect(result).not.toContain('stuvwxyz12345678')
  })

  it('leaves non-secret fields unchanged', () => {
    const input = '{"model":"claude-opus","type":"assistant"}'
    expect(redactSecrets(input)).toBe(input)
  })
})

describe('debugTruncate', () => {
  it('collapses newlines to \\n', () => {
    expect(debugTruncate('line1\nline2')).toBe('line1\\nline2')
  })

  it('returns string unchanged when under limit', () => {
    const s = 'hello'
    expect(debugTruncate(s)).toBe(s)
  })

  it('truncates at 2000 chars and appends length annotation', () => {
    const s = 'x'.repeat(2500)
    const result = debugTruncate(s)
    expect(result).toContain('... (2500 chars)')
    expect(result.startsWith('x'.repeat(2000))).toBe(true)
  })
})

describe('extractErrorDetail', () => {
  it('returns undefined for null', () => expect(extractErrorDetail(null)).toBeUndefined())
  it('returns undefined for non-object', () => expect(extractErrorDetail('oops')).toBeUndefined())
  it('returns undefined when neither field present', () => expect(extractErrorDetail({ code: 404 })).toBeUndefined())

  it('returns data.message when present', () => {
    expect(extractErrorDetail({ message: 'top-level' })).toBe('top-level')
  })

  it('falls through to data.error.message', () => {
    expect(extractErrorDetail({ error: { message: 'nested' } })).toBe('nested')
  })

  it('prefers data.message over data.error.message', () => {
    expect(extractErrorDetail({ message: 'top', error: { message: 'nested' } })).toBe('top')
  })
})

describe('describeAxiosError', () => {
  it('returns plain error message when no response', () => {
    const err = new Error('Network Error')
    expect(describeAxiosError(err)).toBe('Network Error')
  })

  it('appends response data.message when present', () => {
    const err = Object.assign(new Error('Request failed'), {
      response: { data: { message: 'not found' } },
    })
    expect(describeAxiosError(err)).toContain('not found')
  })

  it('appends response data.error.message when data.message absent', () => {
    const err = Object.assign(new Error('Request failed'), {
      response: { data: { error: { message: 'inner error' } } },
    })
    expect(describeAxiosError(err)).toContain('inner error')
  })
})

describe('extractHttpStatus', () => {
  it('returns undefined for plain Error', () => {
    expect(extractHttpStatus(new Error('fail'))).toBeUndefined()
  })

  it('returns undefined for null', () => {
    expect(extractHttpStatus(null)).toBeUndefined()
  })

  it('extracts status from axios-shaped error', () => {
    const err = { response: { status: 404 } }
    expect(extractHttpStatus(err)).toBe(404)
  })

  it('returns undefined when response has no numeric status', () => {
    const err = { response: { status: 'not-a-number' } }
    expect(extractHttpStatus(err)).toBeUndefined()
  })
})
