**Gaps:**
- `computeShimmerSegments`: shimmer fully off left, fully off right, exact boundary, CJK wide chars
- `getBridgeStatus`: all five state combinations (error, reconnecting, sessionActive, connected, idle)
- `computeGlimmerIndex`: cycle wrap

```ts
// tests/bridge/bridgeStatusUtil.test.ts
import { describe, it, expect } from 'bun:test'
import {
  computeShimmerSegments,
  computeGlimmerIndex,
  getBridgeStatus,
  buildIdleFooterText,
  buildActiveFooterText,
  abbreviateActivity,
  timestamp,
} from '../../src/bridge/bridgeStatusUtil.js'

describe('computeShimmerSegments', () => {
  it('returns all text as before when shimmer is off right', () => {
    const { before, shimmer, after } = computeShimmerSegments('hello', 100)
    expect(before).toBe('hello')
    expect(shimmer).toBe('')
    expect(after).toBe('')
  })

  it('returns all text as before when shimmer is off left (negative)', () => {
    const { before, shimmer, after } = computeShimmerSegments('hello', -10)
    expect(before).toBe('hello')
    expect(shimmer).toBe('')
    expect(after).toBe('')
  })

  it('splits text into three segments at mid position', () => {
    const { before, shimmer, after } = computeShimmerSegments('abcde', 2)
    expect(before + shimmer + after).toBe('abcde')
    expect(shimmer.length).toBeGreaterThan(0)
  })
})

describe('computeGlimmerIndex', () => {
  it('cycles based on messageWidth + 20', () => {
    const idx0 = computeGlimmerIndex(0, 10)
    const idx30 = computeGlimmerIndex(30, 10) // cycleLength = 30, so same as tick=0
    expect(idx0).toBe(idx30)
  })

  it('decrements from messageWidth + 10', () => {
    const result = computeGlimmerIndex(0, 10)
    expect(result).toBe(20) // messageWidth(10) + 10 - (0 % 30)
  })
})

describe('getBridgeStatus', () => {
  it('returns failed state on error', () => {
    const s = getBridgeStatus({ error: 'oops', connected: false, sessionActive: false, reconnecting: false })
    expect(s.color).toBe('error')
    expect(s.label).toContain('failed')
  })

  it('returns reconnecting state', () => {
    const s = getBridgeStatus({ error: undefined, connected: false, sessionActive: false, reconnecting: true })
    expect(s.color).toBe('warning')
    expect(s.label).toContain('reconnecting')
  })

  it('returns active state when session is active', () => {
    const s = getBridgeStatus({ error: undefined, connected: false, sessionActive: true, reconnecting: false })
    expect(s.color).toBe('success')
    expect(s.label).toContain('active')
  })

  it('returns active state when connected', () => {
    const s = getBridgeStatus({ error: undefined, connected: true, sessionActive: false, reconnecting: false })
    expect(s.color).toBe('success')
  })

  it('returns connecting state when idle', () => {
    const s = getBridgeStatus({ error: undefined, connected: false, sessionActive: false, reconnecting: false })
    expect(s.color).toBe('warning')
    expect(s.label).toContain('connecting')
  })
})

describe('abbreviateActivity', () => {
  it('truncates strings longer than 30 visual chars', () => {
    const long = 'a'.repeat(50)
    expect(abbreviateActivity(long).length).toBeLessThanOrEqual(33) // 30 + possible ellipsis
  })

  it('preserves strings at or under 30 chars', () => {
    const s = 'short string'
    expect(abbreviateActivity(s)).toBe(s)
  })
})

describe('buildIdleFooterText / buildActiveFooterText', () => {
  it('idle footer embeds the URL', () => {
    expect(buildIdleFooterText('https://example.com')).toContain('https://example.com')
  })

  it('active footer embeds the URL', () => {
    expect(buildActiveFooterText('https://example.com')).toContain('https://example.com')
  })
})
```

