**Gaps:**
- `validateBridgeId`: empty string, path traversal, slash, dot, valid alphanumeric+hyphen+underscore
- `BridgeFatalError`: `name`, `status`, optional `errorType`, `instanceof Error`

```ts
// tests/bridge/bridgeApi.test.ts
import { describe, it, expect } from 'bun:test'
import { validateBridgeId, BridgeFatalError } from '../../src/bridge/bridgeApi.js'

describe('validateBridgeId', () => {
  it('accepts valid alphanumeric IDs', () => {
    expect(validateBridgeId('abc123', 'envId')).toBe('abc123')
  })

  it('accepts IDs with hyphens and underscores', () => {
    expect(validateBridgeId('env-id_001', 'envId')).toBe('env-id_001')
  })

  it('throws on empty string', () => {
    expect(() => validateBridgeId('', 'envId')).toThrow('Invalid envId')
  })

  it('throws on path traversal attempt', () => {
    expect(() => validateBridgeId('../../admin', 'envId')).toThrow('Invalid envId')
  })

  it('throws on ID containing a slash', () => {
    expect(() => validateBridgeId('a/b', 'envId')).toThrow('Invalid envId')
  })

  it('throws on ID containing a dot', () => {
    expect(() => validateBridgeId('a.b', 'envId')).toThrow('Invalid envId')
  })

  it('throws on ID with spaces', () => {
    expect(() => validateBridgeId('a b', 'envId')).toThrow('Invalid envId')
  })
})

describe('BridgeFatalError', () => {
  it('is an instanceof Error', () => {
    expect(new BridgeFatalError('msg', 401)).toBeInstanceOf(Error)
  })

  it('sets name to BridgeFatalError', () => {
    expect(new BridgeFatalError('msg', 403).name).toBe('BridgeFatalError')
  })

  it('exposes status', () => {
    expect(new BridgeFatalError('msg', 403).status).toBe(403)
  })

  it('sets errorType when provided', () => {
    expect(new BridgeFatalError('msg', 410, 'environment_expired').errorType).toBe('environment_expired')
  })

  it('errorType is undefined when omitted', () => {
    expect(new BridgeFatalError('msg', 400).errorType).toBeUndefined()
  })
})
