**Gaps:**
- `createCodeSession`: axios throws (network error → `null`); non-200 status; response missing `cse_` prefix; 201 treated as success
- `fetchRemoteCredentials`: `worker_epoch` as string (proto JSON); `worker_epoch` as non-safe-integer; missing required fields

```ts
// tests/bridge/codeSessionApi.test.ts
import { describe, it, expect, mock } from 'bun:test'

// NOTE: mock axios before importing the module under test
const mockPost = mock(() => Promise.resolve({ status: 200, data: {} }))
mock.module('axios', () => ({ default: { post: mockPost } }))

import {
  createCodeSession,
  fetchRemoteCredentials,
} from '../../src/bridge/codeSessionApi.js'

describe('createCodeSession', () => {
  it('returns null on network error (axios throws)', async () => {
    mockPost.mockRejectedValueOnce(new Error('ECONNREFUSED'))
    const result = await createCodeSession('https://api', 'tok', 'title', 5000)
    expect(result).toBeNull()
  })

  it('returns null on non-200 status', async () => {
    mockPost.mockResolvedValueOnce({ status: 400, data: { message: 'bad request' } })
    const result = await createCodeSession('https://api', 'tok', 'title', 5000)
    expect(result).toBeNull()
  })

  it('returns null when session.id missing cse_ prefix', async () => {
    mockPost.mockResolvedValueOnce({ status: 200, data: { session: { id: 'ses_abc' } } })
    const result = await createCodeSession('https://api', 'tok', 'title', 5000)
    expect(result).toBeNull()
  })

  it('returns session ID on success (200)', async () => {
    mockPost.mockResolvedValueOnce({ status: 200, data: { session: { id: 'cse_abc123' } } })
    const result = await createCodeSession('https://api', 'tok', 'title', 5000)
    expect(result).toBe('cse_abc123')
  })

  it('returns session ID on 201 (created)', async () => {
    mockPost.mockResolvedValueOnce({ status: 201, data: { session: { id: 'cse_xyz' } } })
    const result = await createCodeSession('https://api', 'tok', 'title', 5000)
    expect(result).toBe('cse_xyz')
  })
})

describe('fetchRemoteCredentials', () => {
  it('returns null on network error', async () => {
    mockPost.mockRejectedValueOnce(new Error('timeout'))
    const result = await fetchRemoteCredentials('cse_abc', 'https://api', 'tok', 5000)
    expect(result).toBeNull()
  })

  it('returns null when worker_epoch is not a safe integer', async () => {
    mockPost.mockResolvedValueOnce({
      status: 200,
      data: { worker_jwt: 'jwt', expires_in: 3600, api_base_url: 'https://api', worker_epoch: 9999999999999999 },
    })
    const result = await fetchRemoteCredentials('cse_abc', 'https://api', 'tok', 5000)
    expect(result).toBeNull()
  })

  it('parses worker_epoch as string (proto JSON)', async () => {
    mockPost.mockResolvedValueOnce({
      status: 200,
      data: { worker_jwt: 'jwt', expires_in: 3600, api_base_url: 'https://api', worker_epoch: '42' },
    })
    const result = await fetchRemoteCredentials('cse_abc', 'https://api', 'tok', 5000)
    expect(result?.worker_epoch).toBe(42)
  })

  it('returns null when required fields are missing', async () => {
    mockPost.mockResolvedValueOnce({ status: 200, data: { worker_jwt: 'jwt' } }) // missing others
    const result = await fetchRemoteCredentials('cse_abc', 'https://api', 'tok', 5000)
    expect(result).toBeNull()
  })
})
