**Gaps:**
- `fetchLatestEvents`: axios throws (→ `null`), non-200 status (→ `null`), empty `data` array
- `fetchOlderEvents`: cursor pagination correctly passes `before_id`
- `createHistoryAuthCtx`: result shape (baseUrl, headers)

```ts
// tests/assistant/sessionHistory.test.ts
import { describe, it, expect, mock } from 'bun:test'

const mockGet = mock(() => Promise.resolve({ status: 200, data: { data: [], has_more: false, first_id: null, last_id: null } }))
mock.module('axios', () => ({ default: { get: mockGet } }))

import {
  fetchLatestEvents,
  fetchOlderEvents,
} from '../../src/assistant/sessionHistory.js'
import type { HistoryAuthCtx } from '../../src/assistant/sessionHistory.js'

const ctx: HistoryAuthCtx = {
  baseUrl: 'https://api/v1/sessions/sess_abc/events',
  headers: { Authorization: 'Bearer tok' },
}

describe('fetchLatestEvents', () => {
  it('returns null when axios throws', async () => {
    mockGet.mockRejectedValueOnce(new Error('network'))
    expect(await fetchLatestEvents(ctx)).toBeNull()
  })

  it('returns null on non-200 status', async () => {
    mockGet.mockResolvedValueOnce({ status: 401, data: {} })
    expect(await fetchLatestEvents(ctx)).toBeNull()
  })

  it('returns empty events array on 200 with no data', async () => {
    mockGet.mockResolvedValueOnce({ status: 200, data: { data: [], has_more: false, first_id: null, last_id: null } })
    const page = await fetchLatestEvents(ctx)
    expect(page?.events).toEqual([])
    expect(page?.hasMore).toBe(false)
  })

  it('passes anchor_to_latest=true', async () => {
    mockGet.mockResolvedValueOnce({ status: 200, data: { data: [], has_more: false, first_id: null, last_id: null } })
    await fetchLatestEvents(ctx, 50)
    const [[, config]] = mockGet.mock.calls.slice(-1)
    expect(config.params.anchor_to_latest).toBe(true)
    expect(config.params.limit).toBe(50)
  })
})

describe('fetchOlderEvents', () => {
  it('passes before_id cursor', async () => {
    mockGet.mockResolvedValueOnce({ status: 200, data: { data: [], has_more: false, first_id: 'e1', last_id: null } })
    await fetchOlderEvents(ctx, 'evt_cursor_001')
    const [[, config]] = mockGet.mock.calls.slice(-1)
    expect(config.params.before_id).toBe('evt_cursor_001')
  })

  it('sets hasMore from response', async () => {
    mockGet.mockResolvedValueOnce({ status: 200, data: { data: [{ type: 'user' }], has_more: true, first_id: 'e0', last_id: null } })
    const page = await fetchOlderEvents(ctx, 'e1')
    expect(page?.hasMore).toBe(true)
    expect(page?.events).toHaveLength(1)
  })
})
