// tests/bridge/capacityWake.test.ts
import { describe, it, expect } from 'bun:test'
import { createCapacityWake } from '../../src/bridge/capacityWake.js'

describe('createCapacityWake', () => {
  it('merged signal aborts when outer signal aborts', async () => {
    const outer = new AbortController()
    const cw = createCapacityWake(outer.signal)
    const { signal } = cw.signal()
    expect(signal.aborted).toBe(false)
    outer.abort()
    expect(signal.aborted).toBe(true)
  })

  it('merged signal aborts when wake() is called', () => {
    const outer = new AbortController()
    const cw = createCapacityWake(outer.signal)
    const { signal } = cw.signal()
    expect(signal.aborted).toBe(false)
    cw.wake()
    expect(signal.aborted).toBe(true)
  })

  it('subsequent signal() after wake() produces a fresh unaborted signal', () => {
    const outer = new AbortController()
    const cw = createCapacityWake(outer.signal)
    const first = cw.signal()
    cw.wake()
    expect(first.signal.aborted).toBe(true)
    const second = cw.signal()
    expect(second.signal.aborted).toBe(false)
  })

  it('returns already-aborted signal when outer is pre-aborted', () => {
    const outer = new AbortController()
    outer.abort()
    const cw = createCapacityWake(outer.signal)
    const { signal } = cw.signal()
    expect(signal.aborted).toBe(true)
  })

  it('cleanup() prevents future aborts from the old outer signal', () => {
    const outer = new AbortController()
    const cw = createCapacityWake(outer.signal)
    const { signal, cleanup } = cw.signal()
    cleanup()
    // After cleanup the merged signal is frozen — outer abort should NOT
    // retroactively change it (it's already settled by the AbortController).
    // What we verify: cleanup doesn't throw and the signal was not aborted at call time.
    expect(signal.aborted).toBe(false)
  })
})

